package exam;
import java.util.Scanner;
public class Main {
 private static final Scanner in=new Scanner(System.in);private static String ask(String prompt){System.out.print(prompt);return in.nextLine().trim();}private static int num(String prompt){return Integer.parseInt(ask(prompt));}
 public static void main(String[] args){Store db=new Store(System.getProperty("exam.db","exam-proctoring.db"));ExamFacade facade=new ExamFacade(db);AdminFacade admin=new AdminFacade(db);System.out.println("EXAM PROCTORING — Facade demo");while(true){System.out.println("\n1 Success | 2 Fail at B | 3 Fail at C | 4 Custom | 5 Inspect | 6 Manual rollback | 7 Resume | 0 Exit");try{String choice=ask("Choice: ");if(choice.equals("0"))return;if(choice.matches("[12347]")){String id=ask("Unique exam ID: ");ExamRequest r;if(choice.equals("4")||choice.equals("7")){String student=ask("Student ID: ");int minutes=num("Duration minutes: ");int similarity=num("Similarity 0-100: ");boolean screen=Boolean.parseBoolean(ask("Screen connected (true/false): "));int correct=num("Correct answers: ");int total=num("Total questions: ");boolean recorder=Boolean.parseBoolean(ask("Transcript recorder online (true/false): "));r=new ExamRequest(id,student,minutes,similarity,screen,correct,total,recorder);}else r=new ExamRequest(id,"student001",60,choice.equals("2")?90:12,true,8,10,!choice.equals("3"));System.out.println(choice.equals("7")?facade.resume(r):facade.start(r));System.out.println(admin.inspect(id));}else if(choice.equals("5"))System.out.println(admin.inspect(ask("Exam ID: ")));else if(choice.equals("6")){String id=ask("Exam ID: ");admin.cancel(id);System.out.println(admin.inspect(id));}else System.out.println("Unknown option");}catch(Exception ex){System.out.println("ERROR: "+ex.getMessage());}}}
}
